parameters.jsCode:
// Defensive parse. A model that returns prose instead of JSON must not
// take the lead down with it — we degrade to a safe reply_only turn.
const ctx = $('Prepare WhatsApp Context').first().json;
const raw = $input.first().json;

const text = raw.text ?? raw.output ?? raw.response ?? '';

function extractJson(s) {
  if (!s) return null;
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : s;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try { return JSON.parse(candidate.slice(start, end + 1)); } catch { return null; }
}

const parsed = extractJson(text);
const ok = parsed && typeof parsed.reply === 'string' && parsed.reply.trim();

const ai = ok ? parsed : {
  reply: (text || '').trim().slice(0, 900) ||
    `Hi ${ctx.lead_name || 'there'}, thanks for your interest! How can I help?`,
  intent: 'other',
  qualification_status: ctx.qualification_status || 'unqualified',
  next_action: 'reply_only',
  selected_slot: { date: '', time: '' },
  customer_data: {},
};

// The model is not allowed to book. Only the workflow decides that, and only
// from a slot that was genuinely offered.
const offered = (ctx.conversation_history || [])
  .filter((m) => m.role === 'assistant' && Array.isArray(m.slots))
  .flatMap((m) => m.slots);

let nextAction = ['reply_only', 'check_availability', 'book_appointment', 'handoff_human']
  .includes(ai.next_action) ? ai.next_action : 'reply_only';

const slot = ai.selected_slot || {};
if (nextAction === 'book_appointment') {
  const valid = slot.date && slot.time &&
    (offered.length === 0 || offered.some((s) => s.date === slot.date && s.time === slot.time));
  if (!valid) nextAction = 'check_availability';
}

// Google Calendar wants instants. Convert the chosen wall-clock slot with the
// same fixed offset the slot grid was built from.
const OFF = Number($env.BOOKING_UTC_OFFSET_MINUTES || 330) * 60000;
const LEN = Number($env.BOOKING_SLOT_MINUTES || 60) * 60000;
let slotStartIso = '';
let slotEndIso = '';
if (slot.date && slot.time) {
  const t = Date.parse(`${slot.date}T${slot.time}:00Z`);
  if (!Number.isNaN(t)) {
    slotStartIso = new Date(t - OFF).toISOString();
    slotEndIso = new Date(t - OFF + LEN).toISOString();
  }
}

return [{
  json: {
    ...ctx,
    ai_reply: String(ai.reply).slice(0, 4000),
    intent: ai.intent || 'other',
    qualification_status: ['unqualified', 'qualified', 'disqualified']
      .includes(ai.qualification_status) ? ai.qualification_status : (ctx.qualification_status || 'unqualified'),
    next_action: nextAction,
    selected_slot: slot,
    slot_start_iso: slotStartIso,
    slot_end_iso: slotEndIso,
    ai_customer_data: ai.customer_data || {},
    ai_parse_ok: !!ok,
  },
}];

// The AI errored (rate limit, timeout, bad key). Do not go silent on the
// lead and do not pretend the model spoke — send a neutral holding line.
const ctx = $('Prepare WhatsApp Context').first().json;
return [{
  json: {
    ...ctx,
    ai_reply: `Hi ${ctx.lead_name || 'there'}, thanks for reaching out! One of our team will be with you shortly.`,
    intent: 'other',
    qualification_status: ctx.qualification_status || 'unqualified',
    next_action: 'handoff_human',
    selected_slot: {},
    ai_customer_data: {},
    ai_parse_ok: false,
    ai_error: $json.error?.message ?? 'AI node failed',
  },
}];

// Turn Google's busy periods into the slots we are willing to offer. If the
// calendar call fell over we say so honestly rather than inventing times --
// the prompt forbids the model from having a calendar for exactly this reason.
const ctx = $('Parse AI Reply').first().json;

const MIN = 60000;
const HOUR = 3600000;
const DAY = 86400000;

// Business hours, in the local wall clock. Fixed UTC offset rather than a
// timezone database: the service area (Kolkata, +05:30) has no DST. Move the
// ads to a DST country and this is the knob that has to change.
const OFF = Number($env.BOOKING_UTC_OFFSET_MINUTES || 330) * MIN;
const OPEN = Number($env.BOOKING_OPEN_HOUR || 11);
const CLOSE = Number($env.BOOKING_CLOSE_HOUR || 19);
const LEN = Number($env.BOOKING_SLOT_MINUTES || 60);
const HORIZON_DAYS = 7;
const MAX_SLOTS = 5;
// Never offer a visit that starts before someone could realistically leave.
const MIN_NOTICE_HOURS = 2;

// Shift the epoch by the offset so the plain UTC getters read as local time.
const wall = (ms) => new Date(ms + OFF);
const real = (wallMs) => wallMs - OFF;

// Google freeBusy replies { calendars: { <id>: { busy: [{start,end}], errors } } }.
// neverError + fullResponse means a 4xx arrives as data, so check the status.
const res = $input.first()?.json || {};
const status = res.statusCode ?? 200;
const body = res.body ?? res;
const cals = Object.values(body.calendars || {});
const failed =
  status >= 400 ||
  !!body.error ||
  !body.calendars ||
  cals.some((c) => c && c.errors);

const busy = cals
  .flatMap((c) => (c && c.busy) || [])
  .map((b) => ({ start: Date.parse(b.start), end: Date.parse(b.end) }))
  .filter((b) => !Number.isNaN(b.start) && !Number.isNaN(b.end));

const now = Date.now();
const earliest = now + MIN_NOTICE_HOURS * HOUR;

// Start from today, or from the day the lead asked for if it is still ahead.
const nowWall = wall(now);
let fromWall = Date.UTC(nowWall.getUTCFullYear(), nowWall.getUTCMonth(), nowWall.getUTCDate());
if (/^\d{4}-\d{2}-\d{2}$/.test(ctx.preferred_date || "")) {
  const asked = Date.parse(ctx.preferred_date + 'T00:00:00Z');
  if (!Number.isNaN(asked) && asked > fromWall) fromWall = asked;
}

const slots = [];
// A failed lookup means we do not know what is free. Offering times anyway
// would be the model inventing them by proxy, and Record Delivery would then
// store them as genuinely offered -- enough for a later booking to pass.
for (let d = 0; !failed && d < HORIZON_DAYS && slots.length < MAX_SLOTS; d++) {
  const dayWall = fromWall + d * DAY;
  for (let m = OPEN * 60; m + LEN <= CLOSE * 60 && slots.length < MAX_SLOTS; m += LEN) {
    const start = real(dayWall + m * MIN);
    const end = start + LEN * MIN;
    if (start < earliest) continue;
    if (busy.some((b) => start < b.end && end > b.start)) continue;
    const iso = wall(start).toISOString();
    slots.push({
      date: iso.slice(0, 10),
      time: iso.slice(11, 16),
      start_iso: new Date(start).toISOString(),
      end_iso: new Date(end).toISOString(),
    });
  }
}

let message;
if (failed) {
  message = `${ctx.ai_reply}\n\nI\u2019m having trouble reaching the calendar right now \u2014 I\u2019ll get back to you with times shortly.`;
} else if (!slots.length) {
  message = `${ctx.ai_reply}\n\nWe\u2019re fully booked for the next few days. Would a later date work for you?`;
} else {
  const list = slots.map((s, i) => `${i + 1}. ${s.date} at ${s.time}`).join('\n');
  message = `${ctx.ai_reply}\n\nHere\u2019s what we have open:\n${list}\n\nReply with the number that suits you.`;
}

return [{
  json: {
    ...ctx,
    outbound_message: message,
    offered_slots: slots,
    appointment_status: slots.length ? 'slots_offered' : ctx.appointment_status,
  },
}];

// The single gate that decides whether the lead is told "booked". Google
// returns the created event; anything without an id, a non-2xx, or a
// cancelled event is a failure and the lead gets an honest message instead.
const ctx = $('Parse AI Reply').first().json;
const res = $input.first().json || {};
const status = res.statusCode ?? 200;
const body = res.body ?? res;

const id = body.id ?? '';
const confirmed = status >= 200 && status < 300 && !!id && body.status !== 'cancelled';
const slot = ctx.selected_slot || {};

return [{
  json: {
    ...ctx,
    booking_confirmed: confirmed,
    appointment_id: confirmed ? String(id) : '',
    appointment_status: confirmed ? 'booked' : 'booking_failed',
    appointment_date: confirmed ? slot.date : '',
    appointment_time: confirmed ? slot.time : '',
    appointment_link: confirmed ? (body.htmlLink ?? '') : '',
    booking_error: confirmed
      ? ''
      : (body.error?.message ?? JSON.stringify(body).slice(0, 300)),
    outbound_message: confirmed
      ? `Done! You\u2019re booked for ${slot.date} at ${slot.time}. We\u2019ll send a reminder before then. See you soon!`
      : `I wasn\u2019t able to lock that slot in just now \u2014 someone from our team will confirm with you shortly. Sorry about that!`,
  },
}];

// Record what actually happened, including a WhatsApp failure - the CRM
// must never claim we messaged someone we did not.
// $input is the Send WhatsApp Reply response; the branch that fed it carries
// the state, so pull that from the node that built it.
const prev = $input.first().json;
const status = prev.statusCode ?? 200;
const body = prev.body ?? prev;
const accepted = status >= 200 && status < 300 && !body?.error;
// "accepted" is all a 2xx proves: Meta queued it. Real delivery only arrives
// later on the statuses webhook, so nothing here may claim delivered.
const delivered = accepted;
const usedTemplate = nodeJson('Send WhatsApp Template') !== null;

// Two nodes can produce the conversation state: the normal parse, or the
// fallback when the model failed. Only one of them runs, and asking n8n for a
// node that did not run throws -- which used to kill the run *after* the
// message had already gone out. Whichever exists wins.
function nodeJson(name) {
  try {
    return $(name).first().json;
  } catch {
    return null;
  }
}

const state = nodeJson('Parse AI Reply') ?? nodeJson('AI Failure Fallback');
if (!state) {
  throw new Error('neither Parse AI Reply nor AI Failure Fallback produced state');
}

// $input here is the WhatsApp HTTP response, which does NOT carry the message
// we sent. That lives on whichever of the three branch nodes actually ran.
const branch = ['Pick Send Mode', 'Verify Booking', 'Format Slots Message', 'Prepare Plain Reply']
  .map(nodeJson)
  .find((j) => j && j.outbound_message) ?? {};

const history = [...(state.conversation_history || [])];
if (state.current_message && !state.current_message.startsWith('(no inbound')) {
  history.push({ role: 'user', text: state.current_message, at: new Date().toISOString() });
}
history.push({
  role: 'assistant',
  text: branch.outbound_message ?? state.ai_reply,
  slots: branch.offered_slots ?? [],
  at: new Date().toISOString(),
  delivered,
});

return [{
  json: {
    ...state,
    ...branch,
    whatsapp_accepted: accepted,
    whatsapp_delivered: delivered,
    send_mode: usedTemplate ? 'template' : 'text',
    within_24h: branch.within_24h ?? null,
    window_reason: branch.window_reason ?? '',
    whatsapp_error: accepted ? '' : `status ${status}: ${JSON.stringify(body).slice(0, 300)}`,
    whatsapp_message_id: body?.messages?.[0]?.id ?? '',
    conversation_history_json: JSON.stringify(history.slice(-40)),
    updated_at: new Date().toISOString(),
  },
}];

