// Meta's delivery receipt. This is the only place that knows whether a message
// actually landed - a 200 from the send call only means Meta queued it.
const body = $json.body ?? {};
const entry = body.entry?.[0] ?? {};
const value = entry.changes?.[0]?.value ?? {};
const st = value.statuses?.[0] ?? {};
const err = st.errors?.[0] ?? {};

// entry.id IS the WhatsApp Business Account id. It is not discoverable from the
// access token's scopes, so capture it the first time Meta tells us.
const wabaId = entry.id ?? '';
const staticData = $getWorkflowStaticData('global');
if (wabaId && staticData.waba_id !== wabaId) {
  staticData.waba_id = wabaId;
}
if (value.metadata?.phone_number_id) {
  staticData.phone_number_id = value.metadata.phone_number_id;
}

return [{
  json: {
    waba_id: wabaId,
    phone_number_id: value.metadata?.phone_number_id ?? '',
    wa_id: st.recipient_id ?? '',
    message_id: st.id ?? '',
    delivery_status: st.status ?? '',
    failed: st.status === 'failed',
    conversation_type: st.conversation?.origin?.type ?? '',
    error_code: err.code ?? '',
    error_title: err.title ?? '',
    error_details: err.error_data?.details ?? err.message ?? '',
    at: new Date().toISOString(),
  },
}];

