// Decide free-form vs template BEFORE spending a send on a message that Meta
// will accept and then throw away.
const j = $input.first().json;
const history = j.conversation_history || [];

// An inbound WhatsApp message in this very run opens the window by definition.
const inboundNow = j.source === 'whatsapp_inbound';

const lastInbound = [...history].reverse().find((h) => h.role === 'user' && h.at);
const ageMs = lastInbound ? Date.now() - new Date(lastInbound.at).getTime() : Infinity;
const WINDOW_MS = 24 * 60 * 60 * 1000;
const withinWindow = inboundNow || ageMs < WINDOW_MS;

return [{
  json: {
    ...j,
    within_24h: withinWindow,
    use_template: !withinWindow,
    window_reason: inboundNow
      ? 'inbound message in this run'
      : lastInbound
        ? `last inbound ${Math.round(ageMs / 60000)} min ago`
        : 'no inbound message ever - first contact must be a template',
  },
}];

